recipes.code:
{
  "inputs": [
    {
      "id": "fibx-session-secret",
      "type": "promptString",
      "description": "Encryption key for the local session file. Optional; auto-generated per machine when unset.",
      "password": true
    }
  ],
  "servers": {
    "fibx": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "fibx@0.8.2",
        "mcp-start"
      ],
      "env": {
        "FIBX_API_URL": "<fibx-api-url>",
        "FIBX_SESSION_SECRET": "${input:fibx-session-secret}"
      }
    }
  }
}
